import{_ as a,c as s,G as t,J as e,C as n,a4 as i,V as o,b as l,B as r,D as d}from"./chunks/framework.DULpp8DO.js";const p=JSON.parse('{"title":"解码 Agent Harness：Claude Code 这类编码智能体的运行时到底做了什么","description":"拆解 Claude Code 等编码智能体的运行时（Harness）架构：主循环、工具层、权限系统、子智能体与上下文管理，并给出自研 Harness 的组件清单。","frontmatter":{"title":"解码 Agent Harness：Claude Code 这类编码智能体的运行时到底做了什么","date":"2026-05-22T00:00:00.000Z","categories":["技术分享"],"tags":["Agent Harness","Claude Code","编码智能体","LLM","运行时"],"description":"拆解 Claude Code 等编码智能体的运行时（Harness）架构：主循环、工具层、权限系统、子智能体与上下文管理，并给出自研 Harness 的组件清单。","articleGPT":"很多人以为编码智能体的能力来自模型本身，但实际上\\"同一个模型，Harness 不同，能力天差地别\\"。本文系统拆解 Agent Harness——LLM 之外的所有工程设施：单线程 agentic 主循环如何驱动工具调用、系统提示与 CLAUDE.md 项目记忆如何塑造行为、Read/Edit/Bash/Grep 工具集的设计意图、权限与 hooks 机制、子智能体的上下文隔离，以及 compaction 如何支撑超长任务。文章对比了裸 API + function calling 自研 agent 的能力缺口，最后给出一份自研 Harness 的组件清单，帮你理解智能体的真正护城河在工程层。","cover":"https://lsky.rz15.cn/i/2026/11/19/6afed41c91f5b.png","top":null,"share":true,"delete":false,"head":[["link",{"rel":"canonical","href":"https://ruo.ge/posts/2026-05/20260522"}]]},"headers":[],"relativePath":"posts/2026-05/20260522.md","filePath":"posts/2026-05/20260522.md","lastUpdated":1795486093000}');const h=a({name:"posts/2026-05/20260522.md"},[["render",function(a,p,h,E,c,u){const g=o("Mermaid");return l(),s("div",null,[p[1]||(p[1]=t('<h1 id="解码-agent-harness-claude-code-这类编码智能体的运行时到底做了什么" tabindex="-1">解码 Agent Harness：Claude Code 这类编码智能体的运行时到底做了什么 <a class="header-anchor" href="#解码-agent-harness-claude-code-这类编码智能体的运行时到底做了什么" aria-label="Permalink to &quot;解码 Agent Harness：Claude Code 这类编码智能体的运行时到底做了什么&quot;">​</a></h1><h2 id="一个反直觉的结论-模型不是智能体的全部" tabindex="-1">一个反直觉的结论：模型不是智能体的全部 <a class="header-anchor" href="#一个反直觉的结论-模型不是智能体的全部" aria-label="Permalink to &quot;一个反直觉的结论：模型不是智能体的全部&quot;">​</a></h2><p>2025 年之后，几乎每个团队都试过&quot;用大模型 API + function calling 搭一个自己的 agent&quot;。最常见的剧本是这样的：写一个循环，把用户消息和一堆工具定义塞进 system prompt，模型返回 tool_call 就执行，结果塞回去，直到模型不再调用工具为止。Demo 阶段看起来很惊艳，但一旦放到真实代码库里干活，很快就会暴露出各种问题：改错文件、绕远路、忘记之前的结论、在权限边界上反复横跳、上下文被工具输出撑爆。</p><p>与此同时，Claude Code、Codex CLI 这类产品在同样（甚至更早版本）的模型上表现稳定得多。差距在哪？不在模型，在模型之外的那一层工程设施。这一层，现在通常被称为 <strong>Agent Harness</strong>（智能体运行时/挽具）。</p><p>一句话定义：<strong>Harness = LLM 之外的一切</strong>。它包括 agentic 主循环、工具的定义与执行、权限与安全边界、状态与上下文管理、错误恢复机制。模型是发动机，Harness 是整辆车的底盘、变速箱、刹车和仪表盘。发动机相同，底盘不同，操控感受天差地别。</p><p>这篇文章就把 Claude Code 这类编码智能体的 Harness 拆开来看，里面每个部件为什么长成这个样子。</p><h2 id="harness-的核心-一条单线程-while-循环" tabindex="-1">Harness 的核心：一条单线程 while 循环 <a class="header-anchor" href="#harness-的核心-一条单线程-while-循环" aria-label="Permalink to &quot;Harness 的核心：一条单线程 while 循环&quot;">​</a></h2><p>先破除一个误解：agentic loop 并不复杂。Claude Code 的核心主循环本质上就是：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 极简版 agentic 主循环</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    response </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> llm.chat(messages, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 带着全部上下文请求模型</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.tool_calls:                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 模型不再调工具 =&gt; 任务结束</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        break</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> call </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.tool_calls:             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 逐个执行工具</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> execute_tool(call)              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 真正干活的地方（含权限检查）</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        messages.append(call)                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. 调用记录进上下文</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        messages.append(result)                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 6. 结果进上下文</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>真正的工程含量藏在第 3、4、6 步里：</p><ul><li><strong>单线程、顺序执行</strong>。Claude Code 刻意不搞复杂的并行编排。每轮只有一个推理、一组顺序执行的工具调用。原因很朴素：代码修改是有因果依赖的，并行写入会互相踩踏；而且单线程意味着上下文是一条清晰的因果链，出错时可回溯、可恢复。复杂度全部交给模型去理解，而不是交给编排框架。</li><li><strong>工具结果原样回流</strong>。每次工具调用的完整输出（包括错误）都会进入上下文，模型下一轮看到的是真实世界的反馈，而不是被中间层摘要过的信息。这是 agent 能&quot;自我纠错&quot;的前提——它必须看到失败长什么样。</li><li><strong>终止条件由模型决定</strong>。循环结束不是靠外部编排器判断&quot;任务完成了没&quot;，而是模型自己判断&quot;不用再调工具了&quot;。Harness 只负责兜底：最大轮数、用户打断、致命错误。</li></ul>',11)),(l(),e(i,null,{default:n((()=>[r(g,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E7%94%A8%E6%88%B7%E8%BE%93%E5%85%A5%E4%BB%BB%E5%8A%A1%5D%20--%3E%20B%5B%E6%9E%84%E5%BB%BA%E4%B8%8A%E4%B8%8B%E6%96%87%3Cbr%2F%3E%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%20%2B%20CLAUDE.md%20%2B%20%E5%AF%B9%E8%AF%9D%E5%8E%86%E5%8F%B2%5D%0A%20%20%20%20B%20--%3E%20C%5BLLM%20%E6%8E%A8%E7%90%86%3Cbr%2F%3E%E8%BE%93%E5%87%BA%E6%96%87%E6%9C%AC%E6%88%96%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%5D%0A%20%20%20%20C%20--%3E%20D%7B%E6%98%AF%E5%90%A6%E8%B0%83%E7%94%A8%E5%B7%A5%E5%85%B7%3F%7D%0A%20%20%20%20D%20--%20%E5%90%A6%20--%3E%20E%5B%E8%BE%93%E5%87%BA%E6%9C%80%E7%BB%88%E5%9B%9E%E5%A4%8D%3Cbr%2F%3E%E5%BE%AA%E7%8E%AF%E7%BB%93%E6%9D%9F%5D%0A%20%20%20%20D%20--%20%E6%98%AF%20--%3E%20F%5B%E6%9D%83%E9%99%90%E6%A3%80%E6%9F%A5%3Cbr%2F%3E%E5%85%81%E8%AE%B8%20%2F%20%E6%8B%92%E7%BB%9D%20%2F%20%E8%AF%A2%E9%97%AE%E7%94%A8%E6%88%B7%5D%0A%20%20%20%20F%20--%20%E6%8B%92%E7%BB%9D%20--%3E%20G%5B%E8%BF%94%E5%9B%9E%E6%8B%92%E7%BB%9D%E4%BF%A1%E6%81%AF%3Cbr%2F%3E%E6%A8%A1%E5%9E%8B%E8%B0%83%E6%95%B4%E7%AD%96%E7%95%A5%5D%0A%20%20%20%20G%20--%3E%20C%0A%20%20%20%20F%20--%20%E5%85%81%E8%AE%B8%20--%3E%20H%5B%E6%89%A7%E8%A1%8C%E5%B7%A5%E5%85%B7%3Cbr%2F%3ERead%2FEdit%2FBash%2F...%5D%0A%20%20%20%20H%20--%3E%20I%7B%E4%B8%8A%E4%B8%8B%E6%96%87%E8%B6%85%E9%99%90%3F%7D%0A%20%20%20%20I%20--%20%E6%98%AF%20--%3E%20J%5BCompaction%3Cbr%2F%3E%E5%8E%8B%E7%BC%A9%E5%8E%86%E5%8F%B2%E4%BF%9D%E7%95%99%E5%85%B3%E9%94%AE%E4%BF%A1%E6%81%AF%5D%0A%20%20%20%20J%20--%3E%20C%0A%20%20%20%20I%20--%20%E5%90%A6%20--%3E%20K%5B%E5%B7%A5%E5%85%B7%E7%BB%93%E6%9E%9C%E5%86%99%E5%85%A5%E4%B8%8A%E4%B8%8B%E6%96%87%5D%0A%20%20%20%20K%20--%3E%20C%0A%20%20%20%20E%20--%3E%20L%5B%E7%94%A8%E6%88%B7%E8%BF%BD%E9%97%AE%E6%88%96%E6%96%B0%E4%BB%BB%E5%8A%A1%5D%0A%20%20%20%20L%20--%3E%20B%0A"})])),fallback:n((()=>p[0]||(p[0]=[d(" Loading... ")]))),_:1})),p[2]||(p[2]=t('<h2 id="系统提示与项目记忆-行为塑造的第一现场" tabindex="-1">系统提示与项目记忆：行为塑造的第一现场 <a class="header-anchor" href="#系统提示与项目记忆-行为塑造的第一现场" aria-label="Permalink to &quot;系统提示与项目记忆：行为塑造的第一现场&quot;">​</a></h2><h3 id="系统提示-一份-岗位说明书" tabindex="-1">系统提示：一份&quot;岗位说明书&quot; <a class="header-anchor" href="#系统提示-一份-岗位说明书" aria-label="Permalink to &quot;系统提示：一份&quot;岗位说明书&quot;&quot;">​</a></h3><p>Claude Code 的系统提示相当长，而且写得极其具体。它不是&quot;你是一个编程助手&quot;这种空话，而是大量行为规则：</p><ul><li>语气要求：回复简短直接，不要复述用户的话；</li><li>工具使用偏好：找代码用 Grep/Glob 而不是 ls；</li><li>编辑规范：优先用 Edit 做精确替换，改完不要主动跑格式化；</li><li>沟通纪律：遇到模糊需求先问，破坏性操作先确认。</li></ul><p>这些规则本质上是把&quot;一个好工程师的工作习惯&quot;编译成了 prompt。模型默认行为和工程实践之间有大量缝隙，系统提示就是填缝用的。</p><h3 id="claude-md-分层加载的项目记忆" tabindex="-1">CLAUDE.md：分层加载的项目记忆 <a class="header-anchor" href="#claude-md-分层加载的项目记忆" aria-label="Permalink to &quot;CLAUDE.md：分层加载的项目记忆&quot;">​</a></h3><p>项目记忆通过 <code>CLAUDE.md</code> 文件实现，加载是分层的：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.claude/CLAUDE.md          # 用户级：个人偏好，对所有项目生效</span></span>\n<span class="line"><span>&lt;repo&gt;/CLAUDE.md             # 仓库级：构建命令、代码规范、架构约定</span></span>\n<span class="line"><span>&lt;repo&gt;/src/CLAUDE.md         # 目录级：操作该目录下文件时才注入</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这个设计的精妙之处在于：<strong>项目知识以文件形式存在于代码库里，随代码一起版本管理</strong>。团队成员各自提交自己踩过的坑（&quot;测试要用 pnpm test，npm run test 会跑错目录&quot;），所有人（以及所有人的 agent）自动受益。CLAUDE.md 不是文档，是注入到每次会话上下文里的活配置。</p><p>值得注意的是 Claude Code 后来把这个机制泛化了：<code>@import</code> 语法可以在 CLAUDE.md 里引用其他文件，memory 文件本身也可以用 Read 工具按需读取——这就把&quot;常驻记忆&quot;和&quot;按需检索&quot;连接了起来（这个话题在上下文工程那篇会展开）。</p><h2 id="工具层-每个工具都是一个设计决策" tabindex="-1">工具层：每个工具都是一个设计决策 <a class="header-anchor" href="#工具层-每个工具都是一个设计决策" aria-label="Permalink to &quot;工具层：每个工具都是一个设计决策&quot;">​</a></h2><p>Claude Code 的核心工具集只有十来个：Read、Edit、Write、Bash、Glob、Grep、Task（子智能体）、TodoWrite、WebFetch、WebSearch……数量克制，但每个都有明确的设计意图。</p><h3 id="为什么强调-grep-glob-而不是开放式-ls" tabindex="-1">为什么强调 Grep/Glob 而不是开放式 ls？ <a class="header-anchor" href="#为什么强调-grep-glob-而不是开放式-ls" aria-label="Permalink to &quot;为什么强调 Grep/Glob 而不是开放式 ls？&quot;">​</a></h3><p>一个经典的设计决策：给 agent 提供 ripgrep 封装的 Grep 和模式匹配的 Glob，而<strong>不鼓励</strong>用 <code>ls -R</code> 或 <code>find</code> 漫游目录。</p><p>原因有三：</p><ol><li><strong>输出可控</strong>。Grep 按行返回匹配结果，天然带文件名和行号，输出规模与匹配数成正比；<code>ls -R</code> 在大型仓库里可能吐出上万行，一轮就把上下文吃掉一大块。</li><li><strong>信息密度高</strong>。agent 找代码靠的是语义线索（函数名、字符串常量），Grep 直接命中目标；目录树漫游是人类的探索方式，对 agent 是浪费。</li><li><strong>与下游工具衔接</strong>。Grep 返回 <code>path:line</code> 格式，Read 可以按 offset/limit 精确读取，Edit 可以按 old_string 定位——整个工具链是围绕&quot;精确定位、最小读取&quot;设计的。</li></ol><h3 id="read-的分页与-edit-的精确替换" tabindex="-1">Read 的分页与 Edit 的精确替换 <a class="header-anchor" href="#read-的分页与-edit-的精确替换" aria-label="Permalink to &quot;Read 的分页与 Edit 的精确替换&quot;">​</a></h3><p>Read 工具默认限制读取行数（约 2000 行），超长行截断，支持 offset/limit 分页。这不是功能限制，而是<strong>上下文保护</strong>：让模型养成&quot;先看目录结构，再精确读取&quot;的习惯，而不是一把梭把整个文件塞进上下文。</p><p>Edit 的 <code>old_string/new_string</code> 设计（而非行号 patch）则是为了对抗&quot;模型数错行&quot;——LLM 对行号的感知是出了名地不可靠，而对文本内容的复制是强项。这个设计的细节值得单独一篇，这里先按下不表。</p><h3 id="bash-万能逃生舱口" tabindex="-1">Bash：万能逃生舱口 <a class="header-anchor" href="#bash-万能逃生舱口" aria-label="Permalink to &quot;Bash：万能逃生舱口&quot;">​</a></h3><p>Bash 工具看起来最朴素，其实是整个系统的安全阀。任何内置工具覆盖不了的场景（跑测试、装依赖、查 git 历史），都通过 Bash 兜底。设计上的关键约束是：Bash 输出会被截断（通常几万字符封顶），避免一条失控命令（比如 <code>cat</code> 一个巨大的日志）毁掉整个会话的上下文。</p><h2 id="权限系统与-hooks-安全边界放在-harness-层而不是-prompt-层" tabindex="-1">权限系统与 hooks：安全边界放在 harness 层而不是 prompt 层 <a class="header-anchor" href="#权限系统与-hooks-安全边界放在-harness-层而不是-prompt-层" aria-label="Permalink to &quot;权限系统与 hooks：安全边界放在 harness 层而不是 prompt 层&quot;">​</a></h2><p>很多自研 agent 把安全规则写在系统提示里：&quot;请不要删除文件&quot;。这在 prompt injection 面前不堪一击。Claude Code 的做法是<strong>权限硬边界</strong>：</p><ul><li>工具按风险分级：Read/Grep/Glob 只读免确认；Edit/Bash 默认需要批准（可配置白名单）；</li><li>权限规则可持久化：<code>.claude/settings.json</code> 里配置 <code>Bash(npm test:*)</code> 这类模式，命中即自动放行；</li><li>拒绝也是一种反馈：用户拒绝一次工具调用后，拒绝原因会作为工具结果回流，模型会调整策略而不是硬闯。</li></ul><p><strong>hooks 机制</strong>则提供了用户自定义的干预点：在 PreToolUse、PostToolUse、Stop 等生命周期事件上挂用户脚本，脚本可以拦截、修改或否决工具调用。比如&quot;任何 <code>git push --force</code> 直接阻断&quot;。规则在代码里，不在 prompt 里——这是 harness 思维和 prompt 思维的分水岭。</p><h2 id="子智能体-用上下文隔离换纪律" tabindex="-1">子智能体：用上下文隔离换纪律 <a class="header-anchor" href="#子智能体-用上下文隔离换纪律" aria-label="Permalink to &quot;子智能体：用上下文隔离换纪律&quot;">​</a></h2><p>Task 工具（subagent）是 Claude Code 架构里最容易被低估的一环。它做的事情：派生一个全新的、拥有独立上下文的 agent 实例，交给它一个自包含的任务（比如&quot;搜索这三个模块里所有用到 X 的地方&quot;），干完后<strong>只把最终结论回传到主上下文</strong>。</p><p>这解决了两个问题：</p><ol><li><strong>上下文污染</strong>。一次大规模搜索可能产生几万 token 的中间结果，如果发生在主上下文里，这些噪声会伴随整个会话。子智能体相当于一次性手套——脏活干完就丢。</li><li><strong>注意力稀释</strong>。主上下文里塞满了无关细节后，模型对当前任务的注意力会下降（上下文腐烂问题）。隔离让主 agent 始终保持&quot;干净的案头&quot;。</li></ol><p>代价是信息压缩损耗：子智能体只回传结论，主 agent 看不到过程中的细节。所以什么该派出去（探索、调研、批量验证）、什么必须留在主上下文（核心代码修改），是使用 subagent 的关键判断。</p><h2 id="长任务的三根支柱-todo、compaction-与错误恢复" tabindex="-1">长任务的三根支柱：todo、compaction 与错误恢复 <a class="header-anchor" href="#长任务的三根支柱-todo、compaction-与错误恢复" aria-label="Permalink to &quot;长任务的三根支柱：todo、compaction 与错误恢复&quot;">​</a></h2><h3 id="todowrite-外置的工作记忆" tabindex="-1">TodoWrite：外置的工作记忆 <a class="header-anchor" href="#todowrite-外置的工作记忆" aria-label="Permalink to &quot;TodoWrite：外置的工作记忆&quot;">​</a></h3><p>LLM 在多步任务中的典型病症是&quot;漂移&quot;：做到第 5 步忘了第 2 步的约束。TodoWrite 工具让模型把计划外置成结构化列表（pending/in_progress/completed），每完成一步就更新。这本质上是给模型配了一个<strong>外部工作记忆</strong>，用工具调用的仪式感强制对齐目标。实测中它对 10 步以上任务的完成率影响显著。</p><h3 id="compaction-上下文的垃圾回收" tabindex="-1">Compaction：上下文的垃圾回收 <a class="header-anchor" href="#compaction-上下文的垃圾回收" aria-label="Permalink to &quot;Compaction：上下文的垃圾回收&quot;">​</a></h3><p>会话足够长时，上下文窗口会被打满。Claude Code 的处理方式是 compaction：把对话历史交给模型做一次结构化摘要（保留任务目标、关键决策、文件路径、未完成事项），然后用摘要替换原始历史，会话继续。这相当于给主循环加了一个 GC——它不完美（细节有损），但让&quot;连续工作数小时&quot;成为可能。触发时机和保留策略的细节，同样留到上下文工程那篇展开。</p><h3 id="错误恢复-失败是数据-不是异常" tabindex="-1">错误恢复：失败是数据，不是异常 <a class="header-anchor" href="#错误恢复-失败是数据-不是异常" aria-label="Permalink to &quot;错误恢复：失败是数据，不是异常&quot;">​</a></h3><p>Harness 对错误的态度决定了 agent 的韧性。工具执行失败（测试不过、编译报错、权限拒绝）不会被当成异常抛出终止流程，而是作为普通工具结果回流上下文——模型看到错误信息，下一轮自己想办法。配合 git 的原子性（修改前可回滚），Claude Code 敢于尝试激进的修复方案，失败了退回来换条路。<strong>允许廉价失败，才有真正的自主性。</strong></p><h2 id="对比-裸-api-function-calling-到底缺什么" tabindex="-1">对比：裸 API + function calling 到底缺什么 <a class="header-anchor" href="#对比-裸-api-function-calling-到底缺什么" aria-label="Permalink to &quot;对比：裸 API + function calling 到底缺什么&quot;">​</a></h2><p>把前面所有组件收拢，一张表看清自研 agent 和成熟 harness 的差距：</p><div class="table-container"><table><thead><tr><th>组件</th><th>裸 API 自研</th><th>成熟 Harness</th></tr></thead><tbody><tr><td>主循环</td><td>简单 while，无兜底</td><td>轮数限制、用户打断、错误降级</td></tr><tr><td>项目记忆</td><td>无</td><td>CLAUDE.md 分层加载</td></tr><tr><td>工具集</td><td>随手定义，描述随意</td><td>围绕上下文效率精心设计</td></tr><tr><td>权限</td><td>prompt 里求模型别乱来</td><td>代码层硬边界 + hooks</td></tr><tr><td>长任务</td><td>上下文一满就崩</td><td>compaction + todo 外置记忆</td></tr><tr><td>探索</td><td>全塞主上下文</td><td>subagent 隔离</td></tr><tr><td>失败处理</td><td>异常终止</td><td>错误回流自我纠错</td></tr></tbody></table></div><p>这些缺口单看每一个都不难补，难的是它们要作为一个整体协同工作——这正是&quot;产品级 harness&quot;和&quot;周末项目&quot;的分界线。</p><h2 id="如果你想自研-harness-一份组件清单" tabindex="-1">如果你想自研 Harness：一份组件清单 <a class="header-anchor" href="#如果你想自研-harness-一份组件清单" aria-label="Permalink to &quot;如果你想自研 Harness：一份组件清单&quot;">​</a></h2><p>按优先级排序，最小可用版本的清单如下：</p><ol><li><strong>agentic 主循环</strong>：单线程 while + 工具执行 + 结果回流；设置最大轮数与 token 预算兜底；</li><li><strong>核心工具集</strong>：至少 Read（带分页）、Edit（old/new 精确替换）、Bash（输出截断）、Grep（结构化搜索）；</li><li><strong>权限层</strong>：按工具分级，写操作默认确认，规则落盘可配置；</li><li><strong>系统提示</strong>：行为规则具体化，禁止空话；</li><li><strong>上下文管理</strong>：工具输出截断策略、超限时的 compaction；</li><li><strong>项目记忆</strong>：CLAUDE.md 式的分层加载机制；</li><li><strong>错误处理</strong>：错误作为工具结果回流，不抛异常；</li><li><strong>进阶项</strong>：subagent 隔离、todo 外置记忆、hooks 扩展点、遥测与回放。</li></ol><p>最后说一个心态上的转变：不要试图在编排框架里&quot;预编程&quot;智能体的每一步。Harness 的哲学是<strong>给模型一个足够好的环境，然后信任它</strong>——工具够精确、反馈够真实、边界够清晰，模型自己会找到路。Harness 工程师的产出不是流程图，而是一个让强模型能够充分施展的运行时。</p>',45))])}]]);export{p as __pageData,h as default};
